export type FetchRequestInterceptor = (url: string, init: RequestInit) => RequestInit | Promise<RequestInit>;
export type FetchResponseInterceptor = (response: Response) => Response | Promise<Response>;

/**
 * A security scheme of an operation (the generated client passes them): a bearer token - http bearer, OAuth2, OpenID
 * Connect - from getAccessToken, or an API key from apiKeys (by the scheme's name in components.securitySchemes),
 * sent in the header, query parameter or cookie the scheme declares.
 */
export type SecurityScheme =
  | { readonly type: 'bearer' }
  | { readonly type: 'apiKey'; readonly scheme: string; readonly in: 'header' | 'query' | 'cookie'; readonly name: string };

export interface ApiClientOptions {
  /** The access token, sent as a bearer token with the operations that require one (http bearer, OAuth2, OpenID Connect). */
  getAccessToken?: () => string | Promise<string>;
  /** The API keys of the specification's apiKey security schemes, by scheme name: sent with the operations that require them. */
  apiKeys?: Record<string, string | (() => string | undefined | Promise<string | undefined>)>;
  defaultHeaders?: Record<string, string>;
  requestInterceptors?: FetchRequestInterceptor[];
  responseInterceptors?: FetchResponseInterceptor[];
  /** Retry policy for failed requests. Set to false to disable retry. Defaults to the spec-defined policy. */
  retryPolicy?: RetryPolicy | false;
}

export interface RequestOptions {
  body?: unknown;
  query?: Record<string, string | number | boolean | (string | number | boolean)[] | undefined>;
  headers?: Record<string, string | number | boolean | undefined>;
  /**
   * The operation's security schemes (the generated client passes them): [] for an anonymous operation, which sends
   * no credentials. Without it (a specification that declares no security) the access token is sent when there is one.
   */
  security?: readonly SecurityScheme[];
  signal?: AbortSignal;
  responseType?: 'json' | 'blob' | 'text';
  /** The media type of a file sent as the raw body (the generated client passes the declared one); else the file's own type. */
  contentType?: string;
  /** The result arms of the operation's union (the generated client passes them): a status it does not declare is folded into one it does. */
  arms?: readonly string[];
  /** The readers of the typed headers of the operation's result arms (the generated client passes them). */
  responseHeaders?: ResponseHeaderReaders;
  /** Called for every Server-Sent Event that is yielded as an item, before it is yielded: with the id to send as Last-Event-ID to continue the stream after it. */
  onEvent?: (event: ServerSentEventInfo) => void;
  /** A model or a file (the generated client passes it): a file answer (neither JSON nor XML) is a Blob, a model's is the model. */
  modelOrFile?: boolean;
  /** An XML body (the generated client passes it): the Accept, how to write the request body and read the response. */
  xml?: XmlOptions;
  /** Retry for this request (the generated client passes it for operations with their own x-retry-* settings). */
  retry?: RequestRetry;
}

export type StreamFraming = 'json-array' | 'sse' | 'json-lines' | 'json-seq' | 'multipart';

/**
 * What a Server-Sent Event says besides its data: the id of the last event read (its own, or an earlier one's - an
 * id stays until another is sent; empty when the server has reset it), the event's name (undefined for the unnamed
 * event) and the time in milliseconds the server last asked a client to wait before it reconnects.
 */
export interface ServerSentEventInfo {
  lastEventId?: string;
  event?: string;
  retry?: number;
}

/** Releases a body reader; a stream that was not read to its end is cancelled first, so the connection is closed. */
async function releaseReader(reader: ReadableStreamDefaultReader<Uint8Array>, finished: boolean): Promise<void> {
  if (!finished) {
    await reader.cancel().catch(() => undefined);
  }

  reader.releaseLock();
}

/**
 * The longest record (an event, a JSON Lines line, a JSON Text Sequence record, a JSON array element, a multipart
 * part) a stream reader takes, in characters: a longer one - or a server that never ends one - is a RangeError, not
 * a buffer that grows until the tab or the process runs out of memory. Default: 16 MB. Settable.
 */
export const streamLimits = { maxRecordLength: 16 * 1024 * 1024 };

function guardRecord(length: number): void {
  if (length > streamLimits.maxRecordLength) {
    throw new RangeError(`A streamed record is longer than ${streamLimits.maxRecordLength} characters.`);
  }
}

/**
 * The body of one part of a multipart response - what follows its boundary: past the boundary's padding, the
 * part's headers (a part may have none) and the blank line after them. Null for the closing boundary and for a
 * part whose headers have not ended yet.
 */
function multipartBody(part: string): string | null {
  if (part.startsWith('--')) return null;
  const head = part.replace(/^[ \t]*\r\n/, '');
  if (head.startsWith('\r\n')) return head.substring(2).trim();
  const sep = head.indexOf('\r\n\r\n');
  return sep === -1 ? null : head.substring(sep + 4).trim();
}

async function* parseEventStream<T>(reader: ReadableStreamDefaultReader<Uint8Array>, decoder: TextDecoder, reviver?: (key: string, value: unknown) => unknown, itemEvents?: readonly string[], onEvent?: (event: ServerSentEventInfo) => void): AsyncGenerator<T> {
  let buffer = '';
  let finished = false;
  // The id and the retry time stay until the server sends another, as the standard says
  let lastEventId: string | undefined;
  let retry: number | undefined;
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) {
        finished = true;
        break;
      }
      buffer += decoder.decode(value, { stream: true }).replace(/\r/g, '');
      let sep: number;
      while ((sep = buffer.indexOf('\n\n')) !== -1) {
        guardRecord(sep);
        const rawEvent = buffer.substring(0, sep);
        buffer = buffer.substring(sep + 2);
        const lines = rawEvent.split('\n');
        const eventLine = lines.find((l) => l.startsWith('event:'));
        // An event field without a value names no event
        const eventType = eventLine?.slice(6).trim() || 'message';
        const data = lines
          .filter((l) => l.startsWith('data:'))
          .map((l) => l.slice(5).trimStart())
          .join('\n');
        // An id counts from the end of its event, of an event that is no item as well; one with a NUL and a
        // retry that is not all digits are ignored
        for (const l of lines) {
          if (l.startsWith('id:')) {
            const id = l.slice(3).replace(/^ /, '');
            if (!id.includes('\0')) lastEventId = id;
          } else if (l.startsWith('retry:') && /^\d+$/.test(l.slice(6).trim())) {
            retry = Number(l.slice(6).trim());
          }
        }
        // The item event is the unnamed one (or 'message', the same by the standard), and the ones the operation
        // names (x-sse-item-events): each must be an item. An event without data and any other named event (a
        // heartbeat, a control frame) are read past.
        if ((eventType !== 'message' && !itemEvents?.includes(eventType)) || data.trim().length === 0) continue;
        const item = JSON.parse(data, reviver) as T;
        onEvent?.({ lastEventId, event: eventType === 'message' ? undefined : eventType, retry });
        yield item;
      }
      guardRecord(buffer.length);
    }
  } finally {
    await releaseReader(reader, finished);
  }
}

/** The end (exclusive) of the JSON value that starts at `start`, or -1 while the text holds only part of it. A number or a literal at the text's end is complete only when the stream is. */
function scanJsonValue(text: string, start: number, atEnd: boolean): number {
  const first = text.charAt(start);
  if (first === '{' || first === '[') {
    let depth = 0;
    let inStr = false;
    let esc = false;
    for (let i = start; i < text.length; i++) {
      const ch = text.charAt(i);
      if (inStr) {
        if (esc) {
          esc = false;
        } else if (ch === '\\') {
          esc = true;
        } else if (ch === '"') {
          inStr = false;
        }
        continue;
      }
      if (ch === '"') {
        inStr = true;
      } else if (ch === '{' || ch === '[') {
        depth++;
      } else if (ch === '}' || ch === ']') {
        depth--;
        if (depth === 0) {
          return i + 1;
        }
      }
    }
    return -1;
  }
  if (first === '"') {
    let esc = false;
    for (let i = start + 1; i < text.length; i++) {
      const ch = text.charAt(i);
      if (esc) {
        esc = false;
      } else if (ch === '\\') {
        esc = true;
      } else if (ch === '"') {
        return i + 1;
      }
    }
    return -1;
  }
  let i = start;
  while (i < text.length && !' \t\r\n,]}'.includes(text.charAt(i))) i++;
  return i < text.length || atEnd ? i : -1;
}

/** Reads a JSON array one element at a time; values that are not wrapped in an array are read one after the other. */
async function* parseJsonArrayStream<T>(reader: ReadableStreamDefaultReader<Uint8Array>, decoder: TextDecoder): AsyncGenerator<T> {
  let buffer = '';
  let pos = 0;
  let finished = false;
  let inArray: boolean | undefined;
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) {
        finished = true;
      } else {
        buffer += decoder.decode(value, { stream: true });
      }
      let ended = false;
      while (true) {
        while (pos < buffer.length && ' \t\r\n,'.includes(buffer.charAt(pos))) pos++;
        if (pos >= buffer.length) break;
        if (inArray === undefined) {
          inArray = buffer.charAt(pos) === '[';
          if (inArray) {
            pos++;
            continue;
          }
        }
        // The closing bracket ends the array: it was read to its end, so the reader is released, not cancelled
        // (a body that does not signal its end there, as MSW's, never settles a cancel)
        if (inArray && buffer.charAt(pos) === ']') {
          ended = true;
          finished = true;
          break;
        }
        const end = scanJsonValue(buffer, pos, done);
        if (end === -1) break;
        guardRecord(end - pos);
        yield JSON.parse(buffer.substring(pos, end)) as T;
        pos = end;
      }
      if (ended || done) break;
      if (pos > 0) {
        buffer = buffer.substring(pos);
        pos = 0;
      }
      guardRecord(buffer.length);
    }
  } finally {
    await releaseReader(reader, finished);
  }
}

/** Reads JSON Lines: one value per line, blank lines skipped, a last line without its newline included. */
async function* parseJsonLinesStream<T>(reader: ReadableStreamDefaultReader<Uint8Array>, decoder: TextDecoder): AsyncGenerator<T> {
  let buffer = '';
  let finished = false;
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) {
        finished = true;
        break;
      }
      buffer += decoder.decode(value, { stream: true });
      let nl: number;
      while ((nl = buffer.indexOf('\n')) !== -1) {
        guardRecord(nl);
        const line = buffer.substring(0, nl).trim();
        buffer = buffer.substring(nl + 1);
        if (line.length > 0) yield JSON.parse(line) as T;
      }
      guardRecord(buffer.length);
    }
    const rest = buffer.trim();
    if (rest.length > 0) yield JSON.parse(rest) as T;
  } finally {
    await releaseReader(reader, finished);
  }
}

/** Reads a JSON Text Sequence (RFC 7464): each record is a record separator (0x1E), the JSON text and a newline. */
async function* parseJsonSeqStream<T>(reader: ReadableStreamDefaultReader<Uint8Array>, decoder: TextDecoder): AsyncGenerator<T> {
  let buffer = '';
  let finished = false;
  const parse = (record: string): T | undefined => {
    const text = record.replace(/\x1e/g, '').trim();
    return text.length > 0 ? JSON.parse(text) as T : undefined;
  };
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) {
        finished = true;
        break;
      }
      buffer += decoder.decode(value, { stream: true });
      let rs: number;
      while ((rs = buffer.indexOf('\x1e', 1)) !== -1) {
        guardRecord(rs);
        const item = parse(buffer.substring(0, rs));
        buffer = buffer.substring(rs);
        if (item !== undefined) yield item;
      }
      guardRecord(buffer.length);
      if (buffer.endsWith('\n')) {
        const item = parse(buffer);
        buffer = '';
        if (item !== undefined) yield item;
      }
    }
    const last = parse(buffer);
    if (last !== undefined) yield last;
  } finally {
    await releaseReader(reader, finished);
  }
}

/** Reads one header value from its text: undefined when the text is not such a value. */
export type HeaderValueParser<T> = (text: string | undefined) => T | undefined;

function headerNumber(text: string | undefined): number | undefined {
  const value = text === undefined || text.trim() === '' ? NaN : Number(text);
  return Number.isFinite(value) ? value : undefined;
}

/** The readers of one header value, for the typed headers of a result. */
export const headerValue = {
  /** The text itself. */
  text: (text: string | undefined): string | undefined => text,
  /** A number. */
  number: headerNumber,
  /** A whole number. */
  integer: (text: string | undefined): number | undefined => {
    const value = headerNumber(text);
    return value !== undefined && Number.isInteger(value) ? value : undefined;
  },
  /** true or false, whatever the casing. */
  boolean: (text: string | undefined): boolean | undefined => {
    const value = text?.trim().toLowerCase();
    return value === 'true' ? true : value === 'false' ? false : undefined;
  },
  /** A date or a date-time: ISO 8601, or an HTTP date. */
  date: (text: string | undefined): Date | undefined => {
    if (text === undefined || text.trim() === '') {
      return undefined;
    }

    const value = new Date(text.trim());
    return Number.isNaN(value.getTime()) ? undefined : value;
  },
  /** One of an enum's values. */
  oneOf: <T>(values: readonly (string | number)[]): HeaderValueParser<T> => (text) => {
    const value = text?.trim();
    return values.find((candidate) => String(candidate) === value) as T | undefined;
  },
};

/** Reads the headers of a response for the typed headers of its result. */
export class ResponseHeaderReader {
  private readonly get: (name: string) => string | undefined;

  constructor(get: (name: string) => string | undefined) {
    this.get = get;
  }

  /** A header's text. */
  text(name: string): string | undefined {
    return this.get(name);
  }

  /** A header's value: undefined when it is not a value of its type. */
  value<T>(name: string, parse: HeaderValueParser<T>): T | undefined {
    const text = this.get(name);
    return text === undefined ? undefined : parse(text);
  }

  /** An array header, its items separated by commas: undefined when an item is not a value of its type. */
  list<T>(name: string, parse: HeaderValueParser<T>): T[] | undefined {
    const text = this.get(name);
    if (text === undefined) {
      return undefined;
    }

    const items: T[] = [];
    for (const part of text.split(',')) {
      const item = parse(part.trim());
      if (item === undefined) {
        return undefined;
      }

      items.push(item);
    }

    return items;
  }

  /**
   * An object header in OpenAPI's simple style - name,value,... or name=value,... when exploded - read by the
   * operation's mapping: undefined when the text is not such an object, or a required field is missing.
   */
  object<T>(
    name: string,
    explode: boolean,
    read: (fields: Record<string, string>) => { [K in keyof T]?: T[K] },
    required: readonly (keyof T)[],
  ): T | undefined {
    const text = this.get(name);
    if (text === undefined) {
      return undefined;
    }

    const fields: Record<string, string> = Object.create(null);
    const parts = text.split(',');
    if (explode) {
      for (const part of parts) {
        const at = part.indexOf('=');
        if (at < 0) {
          return undefined;
        }

        fields[part.slice(0, at).trim()] = part.slice(at + 1).trim();
      }
    } else {
      if (parts.length % 2 !== 0) {
        return undefined;
      }

      for (let i = 0; i < parts.length; i += 2) {
        fields[(parts[i] ?? '').trim()] = (parts[i + 1] ?? '').trim();
      }
    }

    const value = read(fields);
    return required.every((key) => value[key] !== undefined) ? value as T : undefined;
  }
}

/** The readers of an operation's typed response headers, by result arm (the generated client passes them). */
export type ResponseHeaderReaders = Partial<Record<string, (header: ResponseHeaderReader) => object>>;

// A header of a Response (several values are joined by commas)
function responseHeader(response: Response, name: string): string | undefined {
  return response.headers.get(name) ?? undefined;
}

// The result with the typed headers of its arm, when the operation declares any for it
function withResponseHeaders<T>(result: ApiResult<T>, readers: ResponseHeaderReaders | undefined): ApiResult<T> {
  const read = readers?.[result.status];
  return read
    ? Object.assign({}, result, { headers: read(new ResponseHeaderReader((name) => responseHeader(result.response, name))) })
    : result;
}

const httpErrorArms: readonly string[] = ['badRequest', 'unauthorized', 'forbidden', 'notFound', 'conflict', 'unprocessableEntity', 'tooManyRequests', 'clientError', 'serverError'];
const successArms = ['ok', 'created', 'accepted', 'noContent'] as const;

/**
 * Folds a result whose status the operation's union does not declare into one it does: an undeclared
 * error status into clientError (4xx) or serverError (5xx), an undeclared success into the declared one.
 */
function fitToArms<T>(result: ApiResult<T>, arms: readonly string[] | undefined): ApiResult<T> {
  if (!arms || arms.includes(result.status)) {
    return result;
  }

  if (httpErrorArms.includes(result.status) && 'error' in result && result.error instanceof ApiError) {
    const status = result.error.status >= 500 ? 'serverError' : 'clientError';
    return { status, error: result.error, response: result.response } as ApiResult<T>;
  }

  const declared = successArms.find((arm) => arms.includes(arm));
  if (declared === undefined || !(successArms as readonly string[]).includes(result.status)) {
    return result;
  }

  return declared === 'noContent'
    ? { status: 'noContent', response: result.response } as ApiResult<T>
    : { status: declared, data: ('data' in result ? result.data : undefined) as T, response: result.response } as ApiResult<T>;
}

/** A body as text, in the charset its Content-Type names (fetch's own text() reads every body as UTF-8). */
async function readText(response: Response): Promise<string> {
  return decodeText(await response.arrayBuffer(), response.headers.get('Content-Type'));
}

export class ApiClient {
  private readonly baseUrl: string;
  private readonly options: ApiClientOptions;
  private readonly retryPolicy: RetryPolicy | false;

  constructor(baseUrl: string, options?: ApiClientOptions) {
    this.baseUrl = baseUrl.replace(/\/+$/, '');
    this.options = options ?? {};
    this.retryPolicy = this.options.retryPolicy !== undefined ? this.options.retryPolicy : defaultRetryPolicy;
  }

  async request<T>(method: string, path: string, options?: RequestOptions): Promise<ApiResult<T>> {
    const url = this.buildUrl(path, { ...options?.query, ...(await this.credentials(options?.security, 'query')) });
    const headers = await this.getHeaders(options?.headers, options?.security);
    if (options?.xml?.accept) {
      headers.set('Accept', options.xml.accept);
    }

    let fetchBody: BodyInit | undefined;
    if (options?.body !== undefined) {
      if (options.body instanceof FormData) {
        fetchBody = options.body;
      } else if (options.body instanceof URLSearchParams) {
        headers.set('Content-Type', 'application/x-www-form-urlencoded');
        fetchBody = options.body;
      } else if (options.body instanceof Blob) {
        headers.set('Content-Type', options.contentType ?? (options.body.type || 'application/octet-stream'));
        fetchBody = options.body;
      } else if (options.xml?.write) {
        headers.set('Content-Type', options.xml.contentType ?? 'application/xml; charset=utf-8');
        fetchBody = options.xml.write(options.body as never);
      } else {
        headers.set('Content-Type', options.contentType ?? 'application/json');
        fetchBody = JSON.stringify(options.body);
      }
    }

    let init: RequestInit = {
      method,
      headers,
      body: fetchBody,
      signal: options?.signal,
    };

    for (const interceptor of this.options.requestInterceptors ?? []) {
      init = await interceptor(url, init);
    }

    const retryPolicy = resolveRetryPolicy(method, this.retryPolicy, options?.retry);
    if (retryPolicy) {
      // Each attempt gets its own signal, so policy.timeoutMs cancels the in-flight fetch and a parent abort
      // reaches every attempt; the body is read inside the attempt, so both cover the body read too.
      return retryWithBackoff(
        (attemptSignal) => fetch(url, { ...init, signal: attemptSignal }),
        retryPolicy,
        options?.signal,
        (response) => this.readResponse<T>(response, options),
      );
    }

    return this.readResponse<T>(await fetch(url, init), options);
  }

  private async readResponse<T>(response: Response, options?: RequestOptions): Promise<ApiResult<T>> {
    for (const interceptor of this.options.responseInterceptors ?? []) {
      response = await interceptor(response);
    }

    // A declared XML error model: read into the model and handed on as a JSON error body - the result keeps the
    // server's response (its headers say XML)
    let serverResponse: Response | undefined;
    const readXmlError = options?.xml?.errors?.[String(response.status)] ?? options?.xml?.errors?.['default'];
    if (readXmlError && !response.ok && isXmlMediaType(response.headers.get('Content-Type'))) {
      try {
        const errorModel = readXmlError(parseXml(await readText(response.clone())));
        const errorHeaders = new Headers(response.headers);
        errorHeaders.set('Content-Type', 'application/json');
        serverResponse = response;
        response = new Response(JSON.stringify(errorModel), { status: response.status, statusText: response.statusText, headers: errorHeaders });
      } catch {
        // Not the declared model: the error arm gets the text
      }
    }

    // An XML body: read by the operation's mapping (no JSON handling)
    if (options?.xml?.read && response.ok && response.status !== 204 && response.status !== 205 && isXmlMediaType(response.headers.get('Content-Type'))) {
      try {
        return withResponseHeaders(fitToArms({ status: xmlSuccessArm(response.status), data: options.xml.read(parseXml(await readText(response))) as T, response } as ApiResult<T>, options.arms), options?.responseHeaders);
      } catch (parseError) {
        return withResponseHeaders(fitToArms({ status: 'parseError', error: parseError as Error, response }, options.arms), options?.responseHeaders);
      }
    }

    return withResponseHeaders(fitToArms(withResponse(serverResponse, await this.handleResponse<T>(response, options?.responseType)), options?.arms), options?.responseHeaders);
  }

  async *requestStream<T>(method: string, path: string, options?: RequestOptions, framing: StreamFraming = 'json-array', sseItemEvents?: readonly string[]): AsyncGenerator<T> {
    const url = this.buildUrl(path, { ...options?.query, ...(await this.credentials(options?.security, 'query')) });
    const headers = await this.getHeaders(options?.headers, options?.security);

    const streamBody = options?.body !== undefined ? JSON.stringify(options.body) : undefined;
    if (streamBody !== undefined) {
      headers.set('Content-Type', 'application/json');
    }

    let init: RequestInit = {
      method,
      headers,
      body: streamBody,
      signal: options?.signal,
    };

    for (const interceptor of this.options.requestInterceptors ?? []) {
      init = await interceptor(url, init);
    }

    // The same pipeline as any request: the response interceptors see the stream's response (a 401 refresh applies)
    let response = await fetch(url, init);
    for (const interceptor of this.options.responseInterceptors ?? []) {
      response = await interceptor(response);
    }

    if (!response.ok) {
      const result = await this.handleResponse<T>(response);
      if ('error' in result) {
        throw result.error;
      }
      throw new ApiError(response.status, response.statusText, 'Stream request failed', response);
    }

    const reader = response.body?.getReader();
    if (!reader) {
      throw new ApiError(0, 'NoBody', 'Response body is empty', response);
    }

    const decoder = new TextDecoder();

    if (framing === 'sse') {
      yield* parseEventStream<T>(reader, decoder, undefined, sseItemEvents, options?.onEvent);
      return;
    }

    if (framing === 'multipart') {
      const contentType = response.headers.get('content-type') ?? '';
      const m = /boundary=("?)([^";]+)\1/i.exec(contentType);
      // Without a boundary the parts cannot be found: an error, not a guess
      if (!m) throw new Error('A multipart/mixed response without a boundary in its Content-Type cannot be split into its parts.');
      const delimiter = '--' + m[2];
      let buf = '';
      let finished = false;
      try {
        while (true) {
          const { done, value } = await reader.read();
          if (done) {
            finished = true;
            // A last part the stream ended on without its closing boundary (the server failed mid-stream): what it sent is yielded
            if (buf.startsWith(delimiter)) {
              const bodyText = multipartBody(buf.substring(delimiter.length)) ?? '';
              if (bodyText.length > 0 && scanJsonValue(bodyText, 0, true) === bodyText.length) yield JSON.parse(bodyText) as T;
            }
            break;
          }
          buf += decoder.decode(value, { stream: true });
          // Discard preamble (everything before the first delimiter boundary).
          const first = buf.indexOf(delimiter);
          if (first === -1) {
            if (buf.length > delimiter.length) buf = buf.substring(buf.length - delimiter.length);
            continue;
          }
          if (first > 0) buf = buf.substring(first);
          // Yield each complete part; buf always starts at a delimiter after this loop.
          while (buf.startsWith(delimiter)) {
            const partStart = delimiter.length;
            const next = buf.indexOf(delimiter, partStart);
            if (next === -1) {
              guardRecord(buf.length - partStart);
              // A part whose body is complete JSON is yielded now, not at the next boundary - a server that fails after it never sends one
              const pending = buf.substring(partStart);
              const pendingBody = multipartBody(pending) ?? '';
              if (pendingBody.length > 0 && pending.endsWith('\r\n') && scanJsonValue(pendingBody, 0, true) === pendingBody.length) {
                yield JSON.parse(pendingBody) as T;
                buf = '';
              }
              break;
            }
            guardRecord(next - partStart);
            const part = buf.substring(partStart, next);
            buf = buf.substring(next);
            const bodyText = multipartBody(part);
            if (bodyText === null) continue;
            if (bodyText.length > 0) yield JSON.parse(bodyText) as T;
          }
        }
      } finally {
        await releaseReader(reader, finished);
      }
      return;
    }

    // JSON Lines, JSON Text Sequence, or a JSON array read one element at a time
    if (framing === 'json-lines') {
      yield* parseJsonLinesStream<T>(reader, decoder);
    } else if (framing === 'json-seq') {
      yield* parseJsonSeqStream<T>(reader, decoder);
    } else {
      yield* parseJsonArrayStream<T>(reader, decoder);
    }
  }

  buildUrl(path: string, query?: Record<string, string | number | boolean | (string | number | boolean)[] | undefined>): string {
    // A relative base URL ('/api', or an empty one) resolves against the origin of the page; without a page
    // (server-side rendering, Node) it stays relative
    const relativeOrigin = 'http://relative.invalid';
    const origin = (globalThis as { location?: { origin?: string } }).location?.origin;
    const url = new URL(`${this.baseUrl}${path}`, origin ?? relativeOrigin);
    if (query) {
      for (const [key, value] of Object.entries(query)) {
        if (value === undefined) {
          continue;
        }
        if (Array.isArray(value)) {
          for (const item of value) {
            url.searchParams.append(key, String(item));
          }
        } else {
          url.searchParams.set(key, String(value));
        }
      }
    }
    // Note: URL.searchParams always percent-encodes values.
    // OpenAPI allowReserved cannot be honoured via this path.
    return url.origin === relativeOrigin ? `${url.pathname}${url.search}${url.hash}` : url.toString();
  }

  async getHeaders(extra?: Record<string, string | number | boolean | undefined>, security?: readonly SecurityScheme[]): Promise<Headers> {
    const headers = new Headers(this.options.defaultHeaders);

    for (const [key, value] of Object.entries(await this.credentials(security, 'headers'))) {
      headers.set(key, value);
    }

    if (extra) {
      for (const [key, value] of Object.entries(extra)) {
        if (value !== undefined) {
          headers.set(key, String(value));
        }
      }
    }

    return headers;
  }

  /**
   * The credentials of an operation's security schemes that go in the headers (the access token as a bearer token, API
   * keys in a header or a cookie) or in the query. Without security schemes - a specification that declares no security -
   * the access token is sent when there is one; an anonymous operation ([]) sends none. A cookie API key is a Cookie
   * header, which browsers do not let a script set (there the browser sends its own cookies): Node only.
   */
  private async credentials(security: readonly SecurityScheme[] | undefined, place: 'headers' | 'query'): Promise<Record<string, string>> {
    const values: Record<string, string> = {};
    const cookies: string[] = [];
    for (const scheme of security ?? [{ type: 'bearer' } as const]) {
      if (scheme.type === 'bearer') {
        if (place === 'headers' && this.options.getAccessToken) {
          values['Authorization'] = `Bearer ${await this.options.getAccessToken()}`;
        }

        continue;
      }

      if ((scheme.in === 'query') !== (place === 'query')) {
        continue;
      }

      const key = this.options.apiKeys?.[scheme.scheme];
      const value = typeof key === 'function' ? await key() : key;
      if (value === undefined) {
        continue;
      }

      if (scheme.in === 'cookie') {
        cookies.push(`${scheme.name}=${encodeURIComponent(value)}`);
      } else {
        values[scheme.name] = value;
      }
    }

    if (cookies.length > 0) {
      values['Cookie'] = cookies.join('; ');
    }

    return values;
  }

  private async handleResponse<T>(response: Response, responseType?: 'json' | 'blob' | 'text'): Promise<ApiResult<T>> {
    // 204 and 205 never carry a body; 304 neither (RFC 9110). The empty body is still read to its end: a
    // browser holds the response open until then, and one left unread is reported as a cancelled request.
    if (response.status === 204 || response.status === 205) {
      await response.arrayBuffer().catch(() => undefined);
      return { status: 'noContent', response };
    }

    if (response.status === 304) {
      await response.arrayBuffer().catch(() => undefined);
      return { status: 'notModified', response };
    }

    const contentType = (response.headers.get('Content-Type') ?? '').toLowerCase();
    const isText = responseType === 'text' || (!responseType && (contentType.startsWith('text/') || contentType.includes('application/xml') || contentType.includes('+xml')));
    const isJson = responseType ? responseType === 'json' : (!isText && (contentType.includes('application/json') || contentType.includes('+json')));

    if (response.ok) {
      // A JSON operation reads JSON whatever the Content-Type says; an empty body is no data. Without a
      // responseType the Content-Type decides, and a body without one is its text (empty: no data).
      let data: unknown;
      try {
        if (isText) {
          data = await readText(response);
        } else if (isJson) {
          const text = await readText(response);
          data = text.length === 0 ? undefined : JSON.parse(text);
        } else if (responseType === 'blob' || contentType.length > 0) {
          data = await response.blob();
        } else {
          const text = await readText(response);
          data = text.length === 0 ? undefined : text;
        }
      } catch (parseError) {
        // Only a malformed body is a parseError; a body read that is aborted or cut off rejects like the request.
        if (!(parseError instanceof SyntaxError)) {
          throw parseError;
        }

        return { status: 'parseError', error: parseError, response };
      }
      const status = response.status === 201
        ? 'created' as const
        : response.status === 202
          ? 'accepted' as const
          : 'ok' as const;
      return { status, data: data as T, response };
    }

    // A 3xx fetch did not follow (300, 305, 306, or redirect: 'manual'): no error - its body, if any.
    if (response.status >= 300 && response.status < 400) {
      let data: unknown = undefined;
      try {
        if (contentType.includes('application/json') || contentType.includes('+json')) {
          data = JSON.parse(await readText(response));
        } else if (contentType.startsWith('text/') || contentType.includes('application/xml') || contentType.includes('+xml')) {
          const text = await readText(response);
          data = text.length > 0 ? text : undefined;
        }
      } catch {
        data = undefined;
      }

      return { status: 'redirection', data, response };
    }

    // The error body is detected from the actual Content-Type (an operation's success responseType
    // says nothing about its errors): a ProblemDetails / declared model / JSON string, or text (text/*, XML).
    // Malformed or empty bodies are non-fatal - the message then falls back to the status text.
    let errorBody: unknown = undefined;
    try {
      if (contentType.includes('application/problem+xml')) {
        const text = await readText(response);
        errorBody = text.length > 0 ? readProblemXml(parseXml(text)) : undefined;
      } else if (contentType.includes('application/json') || contentType.includes('+json')) {
        errorBody = JSON.parse(await readText(response));
      } else if (contentType.startsWith('text/') || contentType.includes('application/xml') || contentType.includes('+xml')) {
        const text = await readText(response);
        errorBody = text.length > 0 ? text : undefined;
      }
    } catch {
      errorBody = undefined;
    }

    const message = errorMessage(response.status, response.statusText, errorBody, contentType);

    if (response.status === 400) {
      // Always badRequest: a 400 without validation errors carries an empty errors map.
      const errors = errorBody !== null && typeof errorBody === 'object' && typeof (errorBody as { errors?: unknown }).errors === 'object' && (errorBody as { errors?: unknown }).errors !== null
        ? (errorBody as { errors: Record<string, string[]> }).errors
        : {};
      return {
        status: 'badRequest',
        error: new ValidationError(response.status, response.statusText, message, errors, response, errorBody),
        response,
      };
    }

    const apiError = new ApiError(response.status, response.statusText, message, response, errorBody);

    switch (response.status) {
      case 401:
        return { status: 'unauthorized', error: apiError, response };
      case 403:
        return { status: 'forbidden', error: apiError, response };
      case 404:
        return { status: 'notFound', error: apiError, response };
      case 409:
        return { status: 'conflict', error: apiError, response };
      case 422:
        return { status: 'unprocessableEntity', error: apiError, response };
      case 429:
        return { status: 'tooManyRequests', error: apiError, response };
      default:
        return response.status >= 400 && response.status < 500
          ? { status: 'clientError', error: apiError, response }
          : { status: 'serverError', error: apiError, response };
    }
  }
}